package com.codepilot1c.core.edt.development;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import java.nio.file.*;
public class VanessaPackagesTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 Map<String,Object> profile()throws Exception {Path r=temp.newFolder().toPath();return new LinkedHashMap<>(Map.of("platform_bin",r.resolve("bin").toString(),"infobase_path",r.resolve("target").toString(),"manager_infobase_path",r.resolve("manager").toString(),"params_template",r.resolve("params.json").toString()));}
 Map<String,Object> artifact()throws Exception {return Map.of("ready",true,"vanessa_epf",temp.getRoot().toPath().resolve("vanessa-automation-single.epf").toString(),"expected_vanessa_sha256","a".repeat(64));}
 @Test public void omittedPairUsesVerifiedDefaultsWithoutMutatingRequest()throws Exception {var p=profile();var calls=new AtomicInteger();var a=artifact();var result=VanessaPackages.profileDefaults(p,()->{calls.incrementAndGet();return a;});assertEquals(1,calls.get());assertFalse(p.containsKey("vanessa_epf"));assertEquals(a.get("vanessa_epf"),result.get("vanessa_epf"));RunnerProfileStore.validateProfile(result,false);}
 @Test public void explicitPairNeverDownloadsOrChangesIt()throws Exception {var p=profile();p.putAll(artifact());p.remove("ready");var result=VanessaPackages.profileDefaults(p,()->{throw new AssertionError("No download expected");});assertEquals(p,result);}
 @Test public void partialOverrideRejectedBeforeDownload()throws Exception {var p=profile();p.put("vanessa_epf",temp.getRoot().toPath().resolve("custom.epf").toString());try{VanessaPackages.profileDefaults(p,()->{throw new AssertionError();});fail();}catch(IllegalArgumentException expected){}}
 @Test public void malformedProfileRejectedBeforeDownload()throws Exception {for(Map<String,Object> p:List.of(new LinkedHashMap<String,Object>(),new LinkedHashMap<String,Object>(Map.of("password","neverstore"))))try{VanessaPackages.profileDefaults(p,()->{throw new AssertionError();});fail();}catch(IllegalArgumentException expected){}}
 @Test public void managerCannotBeTargetEvenWithAutomaticArtifacts()throws Exception {var p=profile();p.put("manager_infobase_path",p.get("infobase_path"));try{VanessaPackages.profileDefaults(p,()->{throw new AssertionError();});fail();}catch(IllegalArgumentException expected){}}
 @Test public void unverifiedPackageCannotFillProfile()throws Exception {try{VanessaPackages.profileDefaults(profile(),()->Map.of("ready",false));fail();}catch(IllegalStateException expected){}}
 @Test public void officialDescriptorsPinThreeDifferentRoles()throws Exception {for(String kind:List.of("vanessa","vanessa-extension","client-mcp")){var s=VerifiedDependencyPackage.bundled("/resources/vanessa/"+kind+".json");assertEquals(kind,s.id());assertEquals("github.com",s.uri().getHost());assertEquals(kind.equals("vanessa")?"zip":"file",s.format());}assertEquals("1.2.043.47",VerifiedDependencyPackage.bundled("/resources/vanessa/vanessa.json").version());}
 @Test public void savingPreparedProfileStillDoesNotClaimLiveReadiness()throws Exception {var p=VanessaPackages.profileDefaults(profile(),()->{try{return artifact();}catch(Exception e){throw new RuntimeException(e);}});var store=new RunnerProfileStore(temp.newFolder().toPath());var result=store.put("OwnFixture","default",p);assertEquals(true,result.get("configured"));assertEquals("configured_not_live_checked",result.get("state"));assertEquals("edt_runner_prepare",result.get("next_tool"));}

 static class DeferredJobs implements RunnerPackageProfilePreparation.Jobs {int starts;boolean active=true;java.util.concurrent.Callable<String> task;public boolean running(String id){return active;}public String start(java.util.concurrent.Callable<String> task){this.task=task;return "job-"+(++starts);}}
 @Test public void coldProfilePutReturnsJobBeforeAnyDownloadOrWriteAndCoalesces()throws Exception {var jobs=new DeferredJobs();var downloads=new AtomicInteger();var prepared=artifact();var service=new RunnerPackageProfilePreparation(jobs,(p,generation)->{downloads.incrementAndGet();return VanessaPackages.profileDefaults(p,()->prepared);});var store=new RunnerProfileStore(temp.newFolder().toPath());var p=profile();var a=service.prepare(store,"OwnFixture","default",p);var b=service.prepare(store,"OwnFixture","default",p);assertEquals(a.get("job_id"),b.get("job_id"));assertEquals(1,jobs.starts);assertEquals(0,downloads.get());assertEquals(false,store.get("OwnFixture","default").get("configured"));jobs.task.call();jobs.active=false;assertEquals(1,downloads.get());assertEquals(true,store.get("OwnFixture","default").get("configured"));}
 @Test public void queuedWorkCannotStartDownloadAfterRestart()throws Exception {
  DependencyPackages.start();var jobs=new DeferredJobs();var downloads=new AtomicInteger();
  var service=new RunnerPackageProfilePreparation(jobs,(p,generation)->{downloads.incrementAndGet();return p;});
  var store=new RunnerProfileStore(temp.newFolder().toPath());service.prepare(store,"OwnFixture","default",profile());
  DependencyPackages.stop();DependencyPackages.start();assertThrows(IllegalStateException.class,()->jobs.task.call());
  assertEquals(0,downloads.get());assertEquals(false,store.get("OwnFixture","default").get("configured"));
 }
 @Test public void cancelledPreparationCannotWriteProfileAfterDefaultsReturn()throws Exception {
  DependencyPackages.start();var jobs=new DeferredJobs();var artifacts=artifact();
  var service=new RunnerPackageProfilePreparation(jobs,(p,generation)->{DependencyPackages.stop();DependencyPackages.start();return VanessaPackages.profileDefaults(p,()->artifacts);});
  var store=new RunnerProfileStore(temp.newFolder().toPath());service.prepare(store,"OwnFixture","default",profile());
  assertThrows(IllegalStateException.class,()->jobs.task.call());assertEquals(false,store.get("OwnFixture","default").get("configured"));
 }
 @Test public void changedArgumentsCannotStartSecondProfileJob()throws Exception {var jobs=new DeferredJobs();var service=new RunnerPackageProfilePreparation(jobs,(p,generation)->{throw new AssertionError();});var store=new RunnerProfileStore(temp.newFolder().toPath());var p=profile();service.prepare(store,"OwnFixture","default",p);p.put("timeout_s",900);try{service.prepare(store,"OwnFixture","default",p);fail();}catch(IllegalStateException expected){}assertEquals(1,jobs.starts);}

 @Test public void explicitPutCannotOvertakeAnActiveAutomaticProfileJob()throws Exception {var jobs=new DeferredJobs();var a=artifact();var service=new RunnerPackageProfilePreparation(jobs,(p,generation)->VanessaPackages.profileDefaults(p,()->a));var store=new RunnerProfileStore(temp.newFolder().toPath());var p=profile();service.prepare(store,"OwnFixture","default",p);var explicit=new LinkedHashMap<>(p);explicit.putAll(a);explicit.remove("ready");try{service.putExplicit(store,"OwnFixture","default",explicit);fail();}catch(IllegalStateException expected){}assertEquals(false,store.get("OwnFixture","default").get("configured"));jobs.task.call();jobs.active=false;assertEquals(true,service.putExplicit(store,"OwnFixture","default",explicit).get("configured"));}
 @Test public void fileChangedWhileDownloadingIsNeverOverwritten()throws Exception {var jobs=new DeferredJobs();var a=artifact();var service=new RunnerPackageProfilePreparation(jobs,(p,generation)->VanessaPackages.profileDefaults(p,()->a));var store=new RunnerProfileStore(temp.newFolder().toPath());var p=profile();service.prepare(store,"OwnFixture","default",p);var newer=new LinkedHashMap<>(p);newer.putAll(a);newer.remove("ready");newer.put("configuration_name","preserve-newer");store.put("OwnFixture","default",newer);try{jobs.task.call();fail();}catch(IllegalStateException expected){}var saved=(Map<?,?>)store.get("OwnFixture","default").get("profile");assertEquals("preserve-newer",saved.get("configuration_name"));}
}
